# fmt: on

def fmt_subjects(subjects):
    inner = ", ".join(f'"{s}"' for s in subjects)
    return f"[{inner}] as const"

def fmt_strings(items):
    return "[" + ", ".join(json.dumps(i) for i in items) + "]"

def fmt_event(e):
    lines = [
        "  {",
        f'    id: {json.dumps(e["id"])},',
        '    kind: "nature",',
        f'    title: {json.dumps(e["title"])},',
        f'    location: {json.dumps(e["location"])},',
        f'    country: {json.dumps(e["country"])},',
        f'    region: {json.dumps(e["region"])},',
        f'    lat: {e["lat"]},',
        f'    lng: {e["lng"]},',
        f'    startDate: {json.dumps(e["startDate"])},',
        f'    endDate: {json.dumps(e["endDate"])},',
        "    animals: [],",
        "    animalLabels: [],",
        f'    natureSubjects: {fmt_subjects(e["natureSubjects"])},',
        f'    subjectLabels: {fmt_strings(e["subjectLabels"])},',
        f'    styles: {fmt_strings(e["styles"])},',
        f'    access: {json.dumps(e["access"])},',
        f'    accommodation: {json.dumps(e["accommodation"])},',
        f'    tourAccess: {json.dumps(e["tourAccess"])},',
        f'    difficulty: {json.dumps(e["difficulty"])},',
        f'    pace: {json.dumps(e["pace"])},',
        f'    danger: {json.dumps(e["danger"])},',
        f'    budgetBand: {json.dumps(e["budgetBand"])},',
        f'    fromAUD: {e["fromAUD"]},',
        f'    description: {json.dumps(e["description"])},',
        f'    gearNotes: {json.dumps(e["gearNotes"])},',
        f'    peakTip: {json.dumps(e["peakTip"])},',
        f'    atmosphere: [{json.dumps(e["atmosphere"][0])}, {json.dumps(e["atmosphere"][1])}],',
        "  },",
    ]
    return "\n".join(lines)

def write_events_ts(events):
    body = "\n".join(fmt_event(e) for e in events)
    content = f'''import type {{ NatureEventDraft }} from "./eventTypes";

/** Landscape, flora, atmospheric, and seasonal nature destinations. */
export const natureEvents: NatureEventDraft[] = [
{body}
];
'''
    EVENTS_PATH.write_text(content, encoding="utf-8")

def write_climates_ts(events):
    lines = ['import type { Climate } from "@/lib/types";', "", "export const NATURE_EVENT_CLIMATES: Record<string, Climate[]> = {"]
    for e in events:
        tags = ", ".join(f'"{c}"' for c in e["climates"])
        lines.append(f'  {json.dumps(e["id"])}: [{tags}],')
    lines.append("};")
    lines.append("")
    CLIMATES_PATH.write_text("\n".join(lines), encoding="utf-8")

