if __name__ == "__main__":
    ids = [e["id"] for e in EVENTS]
    assert len(EVENTS) == 114, f"Expected 114 events, got {len(EVENTS)}"
    assert len(ids) == len(set(ids)), "Duplicate event IDs found"
    missing = set(EXPECTED_IDS) - set(ids)
    extra = set(ids) - set(EXPECTED_IDS)
    if missing:
        raise SystemExit(f"Missing IDs: {sorted(missing)}")
    if extra:
        raise SystemExit(f"Unexpected IDs: {sorted(extra)}")
    write_events_ts(EVENTS)
    write_climates_ts(EVENTS)
    print(f"Wrote {len(EVENTS)} events to {EVENTS_PATH}")
    print(f"Events file lines: {len(EVENTS_PATH.read_text().splitlines())}")
    print(f"Climates file lines: {len(CLIMATES_PATH.read_text().splitlines())}")
